    <div id="join-section">
      <h1 class="play-title"><%= h @game.quiz.title %></h1>
      <p class="play-lead">Enter your name to join the quiz.</p>
      <%= form_with url: play_join_path(code: @game.code), method: :post, local: true, html: { class: "join-form", id: "join-form" } do %>
        <div class="field">
          <label for="player_name">Your name</label>
          <input class="input" type="text" id="player_name" name="player[name]" placeholder="Your name" aria-label="Your name" required autocomplete="off" maxlength="50">
        </div>
        <% if @join_error.present? %>
          <div class="errors"><%= h @join_error %></div>
        <% end %>
        <div class="buttons">
          <button type="submit" class="btn btn--pink">Join</button>
        </div>
      <% end %>
    </div>
    <div id="over-section" style="display:none">
      <div class="play-question__body">The quiz is over</div>
    </div>
  </div>
</div>

<script>
(function() {
  var root = document.getElementById('join-root');
  if (!root) return;
  var stateUrl = root.getAttribute('data-state-url');
  function poll() {
    if (document.hidden) return;
    fetch(stateUrl, { headers: { 'Accept': 'application/json' }, credentials: 'same-origin' })
      .then(function(r) { if (!r.ok) return null; return r.json(); })
      .then(function(d) {
        if (!d) return;
        if (d.is_over || d.game_status === 'ended') {
          var js = document.getElementById('join-section');
          var os = document.getElementById('over-section');
          if (js) js.style.display = 'none';
          if (os) os.style.display = '';
        }
      })
      .catch(function() {});
  }
  setInterval(poll, 200);
  document.addEventListener('visibilitychange', function() { if (!document.hidden) poll(); });
  setTimeout(poll, 100);
})();
</script>
