<%
  # locals: quiz, question, option_rows, errors, form_url, form_method
  is_new = !question.persisted?
%>
<%= form_with url: form_url, method: form_method, local: true, html: { id: "question-form" } do %>
  <div class="field">
    <label for="question_body">Question</label>
    <textarea class="input" rows="3" id="question_body" name="question[body]" required><%= question.body %></textarea>
  </div>

  <div class="field">
    <span class="field-label">Options</span>
    <span class="field-hint">Mark the correct options, at least one. Empty rows are skipped.</span>
  </div>

  <div class="option-rows" id="option-rows">
    <% option_rows.each_with_index do |row, idx| %>
      <% num = idx + 1 %>
      <div class="option-row">
        <div class="field" style="margin-bottom: 0;">
          <label for="option_text_<%= idx %>">Option <%= num %></label>
          <input class="input" type="text" id="option_text_<%= idx %>" name="options[<%= idx %>][text]" value="<%= h row[:text] %>" aria-label="Option <%= num %>">
        </div>
        <span class="checkbox">
          <input type="checkbox" id="option_correct_<%= idx %>" name="options[<%= idx %>][correct]" value="1" <%= "checked" if row[:correct] %> aria-label="Option <%= num %> is correct">
          <label for="option_correct_<%= idx %>">Option <%= num %> is correct</label>
        </span>
      </div>
    <% end %>
  </div>
  <div class="buttons" style="margin-bottom: 28px">
    <button type="button" id="add-option" class="btn btn--ghost btn--sm">Add option</button>
  </div>

  <div class="field">
    <span class="checkbox">
      <input type="checkbox" id="question_active" name="question[active]" value="1" <%= "checked" if question.active? %>>
      <label for="question_active">Active</label>
    </span>
    <span class="field-hint">Only active questions are played.</span>
  </div>

  <% if errors.any? %>
    <div class="errors">
      <ul>
        <% errors.each do |e| %>
          <li><%= e %></li>
        <% end %>
      </ul>
    </div>
  <% end %>

  <div class="buttons">
    <button type="submit" class="btn btn--pink">Save question</button>
    <%= link_to "Cancel", moderate_quiz_path(quiz), class: "btn btn--ghost" %>
  </div>
<% end %>

<script>
(function() {
  var btn = document.getElementById('add-option');
  if (!btn) return;
  btn.addEventListener('click', function() {
    var container = document.getElementById('option-rows');
    var index = container.querySelectorAll('.option-row').length;
    var num = index + 1;
    var div = document.createElement('div');
    div.className = 'option-row';
    // Use DOM methods to avoid quoting issues
    var fieldDiv = document.createElement('div');
    fieldDiv.className = 'field';
    fieldDiv.style.marginBottom = '0';

    var label = document.createElement('label');
    label.setAttribute('for', 'option_text_' + index);
    label.textContent = 'Option ' + num;

    var input = document.createElement('input');
    input.className = 'input';
    input.type = 'text';
    input.id = 'option_text_' + index;
    input.name = 'options[' + index + '][text]';
    input.value = '';
    input.setAttribute('aria-label', 'Option ' + num);

    fieldDiv.appendChild(label);
    fieldDiv.appendChild(input);

    var span = document.createElement('span');
    span.className = 'checkbox';

    var cb = document.createElement('input');
    cb.type = 'checkbox';
    cb.id = 'option_correct_' + index;
    cb.name = 'options[' + index + '][correct]';
    cb.value = '1';
    cb.setAttribute('aria-label', 'Option ' + num + ' is correct');

    var cbLabel = document.createElement('label');
    cbLabel.setAttribute('for', 'option_correct_' + index);
    cbLabel.textContent = 'Option ' + num + ' is correct';

    span.appendChild(cb);
    span.appendChild(cbLabel);

    div.appendChild(fieldDiv);
    div.appendChild(span);
    container.appendChild(div);
  });
})();
</script>
