}

.checkbox { display: inline-flex; gap: 10px; align-items: center; font-weight: 500; cursor: pointer; }

.errors {
  background: var(--c-pink);
  color: var(--c-white);
  border-radius: 12px;
  padding: 14px 18px;
  margin-bottom: 20px;
}
.errors ul { margin: 0; padding-left: 20px; }

/* ---------- Flash ---------- */

.flash {
  position: fixed;
  left: 50%;
  bottom: 24px;
  transform: translateX(-50%);
  z-index: 100;
  background: var(--c-blue);
  color: var(--c-lavender);
  border-radius: 1000px;
  padding: 12px 24px;
  font-weight: 600;
  animation: flash-out 4s forwards;
  pointer-events: none;
}
